template<typename T>
class Container { T value; };

// Explicit instantiation definition (in implementation file)
template class Container<int>;
template class Container<std::string>;

template<typename T>
T max_val(T a, T b) { return (a > b) ? a : b; }

// Explicit instantiation definition for a function
template int max_val<int>(int, int);

// Explicit instantiation declaration (in header file for external linkage)
extern template class Container<double>;
extern template double max_val<double>(double, double);
